  if (!grantResult.ok || !grantData.ok) {
    return { ok: false, error: grantData.error || "wallet_grant_failed", status: 500 };
  }
  const claimRecord = {
    phone: sessionPhone,
    periodType,
    periodKey: targetKey,
    rank: winner.rank,
    prize: winner.prize,
    transactionId: grantData.transaction?.id || requestId,
    claimedAt: Date.now()
  };
  await safePut(env, claimKey, JSON.stringify(claimRecord));
  try {
    await safePut(env, "ranking:claim_log:" + sessionPhone + ":" + Date.now(), JSON.stringify(claimRecord));
  } catch (e) {
  }
  return {
    ok: true,
    status: 200,
    prize: winner.prize,
    rank: winner.rank,
    periodKey: targetKey,
    wallet: grantData.wallet,
    claim: claimRecord
  };
