async function handleDiamondPurchase(env, sessionPhone, packageId, options = {}) {
  if (!PHONE_RE.test(String(sessionPhone || ""))) {
    return { ok: false, error: "auth", status: 401 };
  }
  const pkg = DIAMOND_PACKAGES[packageId];
  if (!pkg) {
    return { ok: false, error: "invalid_package", status: 400 };
  }
  const payWithCoins = !!options.payWithCoins;
  if (payWithCoins) {
    const storeDO = env.ROOM.get(env.ROOM.idFromName("chars:" + sessionPhone));
    const rRead = await storeDO.fetch(
      new Request("https://do/?op=wallet_read", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ phone: sessionPhone })
      })
    );
    const readData = await rRead.json();
    const currentCoins = readData && readData.wallet && Number.isFinite(readData.wallet.coins) ? readData.wallet.coins : 0;
    const requiredCoins = pkg.coinsRequired || pkg.coins;
    if (currentCoins < requiredCoins) {
      return {
        ok: false,
        error: "insufficient_coins",
        message: "\u0633\u06A9\u0647 \u0631\u0648\u0628\u0627\u0647 \u06A9\u0627\u0641\u06CC \u0646\u062F\u0627\u0631\u06CC\u062F! \u0628\u0631\u0627\u06CC \u062E\u0631\u06CC\u062F \u0627\u06CC\u0646 \u0628\u0633\u062A\u0647 \u0628\u0647 " + requiredCoins + " \u0633\u06A9\u0647 \u0646\u06CC\u0627\u0632 \u062F\u0627\u0631\u06CC\u062F (\u0645\u0648\u062C\u0648\u062F\u06CC \u0634\u0645\u0627: " + currentCoins + " \u0633\u06A9\u0647).",
        currentCoins,
        requiredCoins,
        status: 400
      };
    }
    const reqIdSpend = "dm_buy_s_" + crypto.randomUUID();
    const rSpend = await storeDO.fetch(
      new Request("https://do/?op=wallet_spend_coins", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          phone: sessionPhone,
          amount: requiredCoins,
          requestId: reqIdSpend,
          kind: "diamond_pack_purchase",
          itemId: pkg.id
        })
      })
    );
    const dataSpend = await rSpend.json();
    if (!rSpend.ok || !dataSpend.ok) {
      return { ok: false, error: dataSpend.error || "spend_failed", status: 400 };
    }
    const reqIdGems2 = "dm_buy_g_" + crypto.randomUUID();
    const rGems2 = await storeDO.fetch(
      new Request("https://do/?op=wallet_add_diamonds", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          phone: sessionPhone,
          amount: pkg.diamonds,
          requestId: reqIdGems2,
          kind: "diamond_pack_purchase",
          itemId: pkg.id
        })
      })
    );
    const dataGems2 = await rGems2.json();
    if (!rGems2.ok || !dataGems2.ok) {
      return { ok: false, error: dataGems2.error || "grant_failed", status: 500 };
    }
    await recordDiamondScore(env, sessionPhone, pkg.diamonds, "store_purchase", { packageId: pkg.id });
    return {
      ok: true,
      status: 200,
      package: pkg,
      diamondsAdded: pkg.diamonds,
      coinsSpent: requiredCoins,
      wallet: dataGems2.wallet
    };
  }
  const reqIdGems = "dm_buy_g_" + crypto.randomUUID();
  const reqIdCoins = "dm_buy_c_" + crypto.randomUUID();
  const admin = "09921521811";
  const rGems = await env.ROOM.get(env.ROOM.idFromName("chars:" + sessionPhone)).fetch(
    new Request("https://do/?op=assetgrant", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        phone: sessionPhone,
        asset: "gems",
        amount: pkg.diamonds,
        requestId: reqIdGems,
        admin,
        kind: "diamond_pack",
        itemId: pkg.id
      })
    })
  );
  const dataGems = await rGems.json();
  if (!rGems.ok || !dataGems.ok) {
    return { ok: false, error: dataGems.error || "grant_failed", status: 500 };
  }
  let latestWallet = dataGems.wallet;
  if (pkg.coins > 0) {
    const rCoins = await env.ROOM.get(env.ROOM.idFromName("chars:" + sessionPhone)).fetch(
      new Request("https://do/?op=assetgrant", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          phone: sessionPhone,
          asset: "coins",
          amount: pkg.coins,
          requestId: reqIdCoins,
          admin,
          kind: "diamond_bonus_coins",
          itemId: pkg.id
        })
      })
    );
    const dataCoins = await rCoins.json();
    if (dataCoins.ok && dataCoins.wallet) latestWallet = dataCoins.wallet;
  }
  await recordDiamondScore(env, sessionPhone, pkg.diamonds, "store_purchase", { packageId: pkg.id });
  return {
    ok: true,
    status: 200,
    package: pkg,
    diamondsAdded: pkg.diamonds,
    coinsAdded: pkg.coins,
    wallet: latestWallet
  };
}
