async function removeUserFromRanking(env, phone) {
  if (!phone) return;
  try {
    if (globalThis.kvSafeDelete) {
      await globalThis.kvSafeDelete(env, "ranking:user:" + phone);
      await globalThis.kvSafeDelete(env, "ranking:history:" + phone);
      await globalThis.kvSafeDelete(env, "ranking:claim_log:weekly:" + phone);
    } else if (env && env.CHAT && env.CHAT.delete) {
      await env.CHAT.delete("ranking:user:" + phone);
      await env.CHAT.delete("ranking:history:" + phone);
      await env.CHAT.delete("ranking:claim_log:weekly:" + phone);
    }
  } catch (e) {
  }
}
