    var selR = sel >= 0 ? SudokuCore.rowOf(sel) : -1;
    var selC = sel >= 0 ? SudokuCore.colOf(sel) : -1;
    var selB = sel >= 0 ? SudokuCore.boxOf(sel) : -1;

