      var cls = 'sd-cell sudoku-cell';
      var r = SudokuCore.rowOf(i), c = SudokuCore.colOf(i);
      if (c === 2 || c === 5) cls += ' br';
      if (r === 2 || r === 5) cls += ' bl';
      if (given) cls += ' given'; else if (v) cls += ' mine';
      // هایلایت مستقل: ردیف/ستون/بلوک خانهٔ انتخابی + خانه‌های هم‌عدد، هر دو هم‌زمان
