function openSheet(title, text, actions, inputValue){ var o=by('foxSheetOverlay'); if(!o) return; clearTimeout(sheetTimer); if(!o.classList.contains('show'))sheetReturnFocus=document.activeElement; o.innerHTML=''; var card=document.createElement('div'); card.className='fox-sheet';card.setAttribute('role','dialog');card.setAttribute('aria-modal','true');card.setAttribute('aria-label',title); var grip=document.createElement('div'); grip.className='fox-sheet-grip'; card.appendChild(grip); var h=document.createElement('h3'); h.textContent=title; card.appendChild(h); if(text){var p=document.createElement('p');p.textContent=text;card.appendChild(p);} var input=null; if(inputValue!==undefined){input=document.createElement('textarea');input.className='fox-sheet-input';input.rows=3;input.value=inputValue||'';card.appendChild(input);} var a=document.createElement('div');a.className='fox-sheet-actions';(actions||[]).forEach(function(item){var b=document.createElement('button');b.type='button';b.textContent=item.label;b.className=(item.kind||'')+(item.selected?' selected':'');if(item.selected!==undefined)b.setAttribute('aria-pressed',String(!!item.selected));b.addEventListener('click',function(){ if(item.close!==false) closeSheet(); if(item.onClick) item.onClick(input?input.value:''); });a.appendChild(b);});card.appendChild(a);o.appendChild(card);o.classList.add('show');o.onclick=function(e){if(e.target===o)closeSheet();};var first=card.querySelector('textarea,button');if(first)first.focus();o.onkeydown=function(e){if(e.key==='Escape'){e.preventDefault();closeSheet();}if(e.key==='Tab'){var fs=card.querySelectorAll('button,textarea');var a=fs[0],z=fs[fs.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}}};if(input)setTimeout(function(){input.focus();input.selectionStart=input.value.length;},160); }
