/* ================= utils ================= */
function $(id){ return document.getElementById(id); }
function faNum(n){ n=String(n); var s=''; for(var i=0;i<n.length;i++){ var c=n[i]; s+=(c>='0'&&c<='9')?'\u06F0\u06F1\u06F2\u06F3\u06F4\u06F5\u06F6\u06F7\u06F8\u06F9'[+c]:c; } return s; }
function faTime(sec){ sec=Math.max(0,Math.round(sec)); return faNum(Math.floor(sec/60))+':'+faNum(('0'+(sec%60)).slice(-2)); }
function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function lerp(a,b,t){ return a+(b-a)*t; }
function rnd(a,b){ return a+Math.random()*(b-a); }
function prand(seed){ var a=seed>>>0; return function(){ a|=0; a=(a+0x6D2B79F5)|0; var t=Math.imul(a^(a>>>15),1|a); t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; }; }
/* ---- deterministic branch pattern (MUST match server) ---- */
function h32(a){ a|=0; a=Math.imul(a^(a>>>15),2246822519); a=Math.imul(a^(a>>>13),3266489917); return (a^(a>>>16))>>>0; }
function rhash(seed,row){ return h32((seed^Math.imul(row+1,0x9E3779B9))|0); }
function bHas(seed,row){ if(row<6) return false; var d=Math.min(.62,.26+row*.006); return (rhash(seed,row)%1000)/1000<d; }
function bSide(seed,row){ return rhash(seed+7,row+13)%2; }
function branchInfo(seed,row){
  if(row<6) return null;
  if(bHas(seed,row-1)) return null;
  if(!bHas(seed,row)) return null;
  return {side:bSide(seed,row)};
}

/* ================= audio ================= */
var AC=null, muted=false;
function ac(){ if(!AC){ try{ AC=new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(AC&&AC.state==='suspended') AC.resume(); return AC; }
function tone(f,dur,type,vol,delay){ var a=AC; if(!a||muted) return; type=type||'sine'; vol=vol||.2; delay=delay||0;
  var t=a.currentTime+delay,o=a.createOscillator(),g=a.createGain();
  o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+dur+.02); }
function noiseBurst(dur,freq,vol,q,delay){ var a=AC; if(!a||muted) return; delay=delay||0;
  var t=a.currentTime+delay,len=Math.floor(a.sampleRate*dur),buf=a.createBuffer(1,len,a.sampleRate),d=buf.getChannelData(0);
  for(var i=0;i<len;i++) d[i]=(Math.random()*2-1)*(1-i/len);
  var s=a.createBufferSource();s.buffer=buf;
  var f=a.createBiquadFilter();f.type='bandpass';f.frequency.value=freq;f.Q.value=q||1;
  var g=a.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  s.connect(f);f.connect(g);g.connect(a.destination);s.start(t); }
var SFX={
  click:function(){ tone(700,.06,'triangle',.12); },
  found:function(){ tone(660,.1,'sine',.2); tone(880,.14,'sine',.2,.1); },
  beep:function(){ tone(880,.09,'square',.08); },
  go:function(){ tone(1320,.25,'square',.1); },
  swing:function(){ noiseBurst(.1,2600,.09,1.4); },
  chop:function(){ noiseBurst(.09,700,.5,.8); tone(95,.12,'triangle',.5); },
  step:function(){ noiseBurst(.05,500,.15,1); },
  crash:function(){ noiseBurst(.4,300,.6,.7); tone(70,.5,'sawtooth',.35); },
  win:function(){ [523,659,784,1046].forEach(function(f,i){ tone(f,.22,'triangle',.16,i*.11); }); },
  lose:function(){ [392,311,233].forEach(function(f,i){ tone(f,.3,'sine',.16,i*.16); }); }
};
$('btnSound').addEventListener('click',function(){ muted=!muted; $('btnSound').textContent=muted?'\u{1F507}':'\u{1F50A}'; try{localStorage.setItem('fox_timber_mute',muted?'1':'');}catch(e){} });
try{ muted=localStorage.getItem('fox_timber_mute')==='1'; $('btnSound').textContent=muted?'\u{1F507}':'\u{1F50A}'; }catch(e){}

