try{ var _u=JSON.parse(localStorage.getItem('fox_user')||'null'); if(_u&&_u.phone){ ME.phone=String(_u.phone); ME.name=String(_u.name||'\u0628\u0627\u0632\u06CC\u06A9\u0646').slice(0,20);} }catch(e){}
