/* ================= images ================= */
var BLUE_TINT='hue-rotate(165deg) saturate(1.25) brightness(1.03)';
var imgs={ready:new Image(),chop:new Image(),run:new Image(),win:new Image(),hero:new Image(),axes:[]};
imgs.ready.src=IMG_READY; imgs.chop.src=IMG_CHOP; imgs.run.src=IMG_RUN; imgs.win.src=IMG_WIN; imgs.hero.src=IMG_HERO;
for(var ai=0;ai<IMG_AXES.length;ai++){ var im=new Image(); im.src=IMG_AXES[ai]; imgs.axes.push(im); }
imgs.env={}; for(var ei=0;ei<ENVS.length;ei++){ var im2={card:new Image(),lobby:new Image(),game:new Image()};
  im2.card.src=TENV_IMG[ENVS[ei].art].card; im2.lobby.src=TENV_IMG[ENVS[ei].art].lobby; im2.game.src=TENV_IMG[ENVS[ei].art].game;
  imgs.env[ENVS[ei].art]=im2; }

/* ================= canvas ================= */
var cv=$('cv'), ctx=cv.getContext('2d'), DPR=1, W=0, H=0;
function resize(){ DPR=Math.min(2,window.devicePixelRatio||1); W=window.innerWidth; H=window.innerHeight;
  cv.width=Math.floor(W*DPR); cv.height=Math.floor(H*DPR); ctx.setTransform(DPR,0,0,DPR,0,0); layoutScenes(); }
window.addEventListener('resize',resize);

/* ================= state ================= */
var MODE=null, RUN=null, scenes=[], particles=[], shake=0, lastT=0, ambT=0;


function layoutScenes(){
  if(!scenes.length) return;
  if(scenes.length===1){ scenes[0].rect={x:0,y:0,w:W,h:H}; }
  else if(W>=H){ scenes[0].rect={x:0,y:0,w:W/2,h:H}; scenes[1].rect={x:W/2,y:0,w:W/2,h:H}; }
  else { scenes[0].rect={x:0,y:H*.42,w:W,h:H*.58}; scenes[1].rect={x:0,y:0,w:W,h:H*.42}; }
  scenes.forEach(function(s){ var g=geom(s); s.foxXa=slotX(s,g,s.foxSide); });
}
function geom(s){
  var r=s.rect;
  var rowH=clamp(r.h*.115,40,92);
  var trunkW=clamp(rowH*.92,30,74);
  var groundY=r.y+r.h*.88;
  var trunkX=r.x+r.w*.5;
  var foxH=rowH*1.62;
  return {rowH:rowH,trunkW:trunkW,groundY:groundY,trunkX:trunkX,foxH:foxH};
}
function slotX(s,g,side){ return g.trunkX + (side===0?-1:1)*(g.trunkW/2 + g.foxH*.30); }

/* ================= render ================= */







/* ---------------- fox ---------------- */
function drawFox(s,g,dt){
  var f={};
  var pose='ready', rot=0, dx=0, dy=0, axeRot=GRIP.ready.r, img=imgs.ready;
  if(s.dead){ pose='ready'; img=imgs.ready; rot=.22; dy=3; axeRot=GRIP.lose.r; }
  else if(s.won){ pose='win'; img=imgs.win; axeRot=GRIP.win.r; s.deadT+=dt; dy=-Math.abs(Math.sin(s.deadT*6))*12; rot=Math.sin(s.deadT*6)*.05; }
  else if(s.swing){
    var T=s.swing.t;
    if(T<100){ img=imgs.ready; axeRot=lerp(GRIP.ready.r,-.55,T/100); rot=-.06*(T/100); }
    else if(T<190){ img=imgs.chop; axeRot=GRIP.chop.r; rot=lerp(-.06,.09,(T-100)/90); dx=5; }
    else if(T<300){ img=imgs.chop; axeRot=GRIP.chop.r; rot=.09; dx=5; }
    else if(T<430){ var k=(T-300)/130; img=imgs.ready; axeRot=lerp(GRIP.chop.r,GRIP.ready.r,k*k); rot=lerp(.09,0,k); dx=lerp(5,0,k); }
    else s.swing=null;
  }
  else if(s.moving){ pose='run'; img=imgs.run; axeRot=GRIP.run.r; dy=-Math.abs(Math.sin(s.moveT*22))*3; rot=(s.foxSide===0?-1:1)*.06; }
  else { /* idle breathing, feet locked */
    var br2=Math.sin(ambT*2.2+s.id*2);
    dy=0; rot=0; axeRot=GRIP.ready.r+br2*.03;
  }
  if(!img.complete||!img.naturalWidth) img=imgs.ready;
  if(!img.complete||!img.naturalWidth){ return; }
  var h=g.foxH, sc=h/img.naturalHeight, w=img.naturalWidth*sc;
  var fx=s.foxXa+dx, fy=g.groundY+dy*0; /* feet ALWAYS on ground */
  /* shadow */
  ctx.fillStyle=(palOf(s).id==='def'?'rgba(20,40,20,.28)':'rgba(0,0,0,.34)');
  ctx.beginPath(); ctx.ellipse(s.foxXa,g.groundY+3,w*.32,5.5,0,0,7); ctx.fill();
  ctx.save();
  ctx.translate(fx,fy);
  /* fox must face the trunk: native sprite faces right */
  var faceL = (s.foxSide===1);
  if(faceL !== !!s.mirror) ctx.scale(-1,1);
  ctx.rotate(rot);
  if(s.tint&&ctx.filter!==undefined){ try{ ctx.filter=s.tint; }catch(e){} }
  ctx.drawImage(img,-w*.55,-h,w,h);
  /* axe in hands */
  var ga=GRIP[pose==='win'?'win':(img===imgs.chop?'chop':(img===imgs.run?'run':'ready'))];
  var ax=imgs.axes[(RUN&&RUN.axe!=null)?RUN.axe:selAxe];
  if(ax&&ax.complete&&ax.naturalWidth){
    var al=h*.92, aw=ax.naturalWidth*(al/ax.naturalHeight);
    ctx.save();
    ctx.translate((-w*.55)+ga.x*w, (-h)+ga.y*h);
    ctx.rotate(axeRot);
    ctx.drawImage(ax,-aw*.5,-al*.66,aw,al);
    ctx.restore();
  }
  ctx.filter='none';
  ctx.restore();
}

/* ---------------- particles ---------------- */





/* ================= gameplay ================= */
function axeOf(){ return AXES[(RUN&&RUN.axe!=null)?RUN.axe:selAxe]; }
function doChop(side){
  if(!RUN||RUN.screen!=='play') return;
  var s=scenes[0]; if(!s||s.dead||s.won) return;
  if(s.swing) return;                    /* exactly one swing per tap */
  var now=performance.now();
  if(now-s.lastChopT < axeOf().cd) return;
  s.lastChopT=now;
  if(s.foxSide!==side){ s.foxSide=side; s.moving=true; s.moveT=0; SFX.step(); }
  s.swing={t:0,side:side,imp:false};
  SFX.swing();
}
function updateMove(s,dt){
  var g=geom(s), tx=slotX(s,g,s.foxSide);
  if(s.moving){
    s.moveT+=dt;
    s.foxXa=lerp(s.foxXa,tx,Math.min(1,dt*16));
    if(Math.abs(s.foxXa-tx)<1.5||s.moveT>.22){ s.foxXa=tx; s.moving=false; }
  } else s.foxXa=tx;
}

function spawnStump(s,g,side){
  var dirF=side===0?-1:1; /* chopped piece is knocked away from the fox */
  s.parts.push({k:'log',x:g.trunkX,y:g.groundY-g.rowH*.95,vx:-dirF*rnd(170,320),vy:rnd(-340,-200),rot:-dirF*.15,vr:-dirF*rnd(3.5,7),t:0,life:.95,w:g.trunkW,h:g.rowH*.92});
}
function spawnFall(s,g,row,side){
  var dir=side===0?-1:1;
  var y=g.groundY-(row-s.rowsAnim)*g.rowH-g.rowH*.5;
  s.parts.push({k:'fall',x:g.trunkX+dir*g.trunkW*.55,y:y,vx:dir*rnd(40,110),vy:rnd(-60,20),rot:0,vr:dir*rnd(2,5),t:0,life:.9,len:g.rowH*1.4,side:side});
}
/* input: tap side = move + chop */
cv.addEventListener('pointerdown',function(e){ ac();
  if(!RUN||RUN.screen!=='play') return;
  var s=scenes[0]; if(!s) return;
  var g=geom(s);
  var x=e.clientX, y=e.clientY;
  if(scenes.length===2){ /* only my half */
    var r0=s.rect;
    if(x<r0.x||x>r0.x+r0.w||y<r0.y||y>r0.y+r0.h){ /* allow anyway on portrait split */ }
  }
  doChop(x < g.trunkX ? 0 : 1);
});
document.addEventListener('keydown',function(e){
  if(e.code==='ArrowLeft'||e.code==='KeyA') doChop(0);
  else if(e.code==='ArrowRight'||e.code==='KeyD') doChop(1);
  else if(e.code==='Space'){ var s=scenes[0]; if(s) doChop(s.foxSide); }
});

