HL_RULES.c=HL_RULES.cpp;HL_RULES.csharp=HL_RULES.java;HL_RULES.golang=HL_RULES.javascript;
HL_RULES.rust=HL_RULES.javascript;HL_RULES.ruby=HL_RULES.python;HL_RULES.kotlin=HL_RULES.javascript;
HL_RULES.swift=HL_RULES.javascript;HL_RULES.dart=HL_RULES.javascript;HL_RULES.php=HL_RULES.javascript;
