  FoxAIChat.authPhone=''; FoxAIChat.serverAuthenticated=false; FoxAIChat.isMenuOpen=false; FoxAIChat.isHistoryOpen=false; FoxAIChat.isCreatingConversation=false; FoxAIChat.isDeletingConversation=false; FoxAIChat.isSendingMessage=false; FoxAIChat.isGeneratingResponse=false; FoxAIChat.isStoppingResponse=false; FoxAIChat.isConfirmDeleteOpen=false; FoxAIChat.dailyFreeMessagesUsed=0; FoxAIChat.dailyFreeMessageLimit=14; FoxAIChat.dailyResetDate=''; FoxAIChat.messageError=''; FoxAIChat.conversationError='';
  FoxAIHistory={all:function(){return (FoxAIChat.conversationList||[]).slice();},get:function(id){var a=FoxAIChat.conversationList||[];for(var i=0;i<a.length;i++)if(a[i].id===id)return a[i];return null;},put:function(){},getActiveId:function(){return FoxAIChat.activeConversationId||null;},setActiveId:function(){}};
