/* public surface (debugging + future extensions) */
window.FoxAI={
  chat:FoxAIChat, service:FoxAIService, models:FoxAIModels, providers:FoxAIProviders,
  history:FoxAIHistory, mock:mockCfg,
  ui:{toast:toast, openSheet:openSheet, closeSheet:closeSheet, openMenu:openMenu, closeMenu:closeMenu, openLightbox:openLightbox},
  controller:{send:sendFromComposer, chat:runChat, analyze:runAnalyze, generate:runGenerate,
    retry:retryMessage, regen:regenerateMessage, cancel:cancelSending, select:selectModel,
    newConv:newConversation, attach:attachFiles, removeAtt:removeAttachment}
};
if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', init); }
